<script setup>import { ref } from 'vue'; import AppIcon from '../../components/AppIcon.js'; import UiButton from '../../components/UiButton.vue'; const props=defineProps({application:Object,active:Boolean}), emit=defineEmits(['navigate','notify']), open=ref(true); async function select(id){await props.application.select(id);emit('navigate','talk')} async function remove(id){if(confirm('删除这个 Talk？')) await props.application.remove(id)}</script>
<template><section class="side-section"><header><button type="button" class="side-section__toggle" :aria-expanded="open" @click="open=!open"><AppIcon name="scope-talk"/><span>Talk</span><AppIcon class="section-chevron" :class="{'section-chevron--open':open}" name="chevron" size="12"/></button><UiButton variant="ghost" size="icon" title="新建 Talk" @click="emit('navigate','talk-create')"><AppIcon name="plus" size="14"/></UiButton></header><div v-show="open" class="side-list"><div v-for="item in application.talks" :key="item.id" class="conversation-entry" :class="{active:active&&application.ui.activeTalkId===item.id}"><button @click="select(item.id)"><span>{{item.name}}</span></button><UiButton variant="ghost" size="icon" title="删除 Talk" @click="remove(item.id)"><AppIcon name="trash" size="14"/></UiButton></div><p v-if="!application.talks.length" class="side-list__empty">还没有 Talk</p></div></section></template>
